function readLegacyArray(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch(e){return[]}}
function normalizeRecipeLegacyItem(item,legacyIngredients,legacyProducts,legacyPreps){
 const x={...(item||{})}; const type=String(x.type||'ingredient').toLowerCase();
 const ref=String(x.ref??x.ingredientId??x.productId??'');
 if(type==='prep'){
   const pr=legacyPreps.find(p=>String(p.id)===ref)||legacyPreps.find(p=>normMaster(p.name)===normMaster(x.product||x.ingredient||x.name||''));
   if(pr){x.product=x.product||pr.name;x.ingredient=x.ingredient||pr.name;x.prepId=pr.id;x.ref=pr.id;x.type='prep';x.unit=x.unit||pr.yieldUnit||'unidad';}
 }else{
   const ing=legacyIngredients.find(i=>String(i.id)===ref)||legacyIngredients.find(i=>normMaster(i.name)===normMaster(x.product||x.ingredient||x.name||''));
   const pid=ing?.productId||x.productId||'';
   const prod=legacyProducts.find(p=>String(p.id)===String(pid))||legacyProducts.find(p=>normMaster(p.name)===normMaster(ing?.productName||x.product||x.ingredient||x.name||''));
   if(ing){x.ingredient=ing.name;x.product=x.product||ing.productName||ing.name;x.ingredientId=ing.id;}
   if(prod){x.product=prod.name;x.productId=prod.id;}
   x.type='ingredient';x.ref=x.ingredientId||x.productId||ref;x.unit=x.unit||ing?.unit||prod?.unit||'unidad';
 }
 return x;
}
function hydrateLegacyRecipeStores(){
 const legacyFinal=readLegacyArray('lrx_finalrecipes_v3'), legacyPrep=readLegacyArray('lrx_preparations_v2');
 const legacyIngredients=readLegacyArray('lrx_ingredients_v1'), legacyProducts=readLegacyArray('lrx_products');
 const allLegacy=[...legacyFinal.map(x=>({...x,type:x.type||'final'})),...legacyPrep.map(x=>({...x,type:'pre'}))];
 if(!allLegacy.length)return;
 const byId=new Map((master.recipes||[]).map(x=>[String(x.id),x]));
 const byName=new Map((master.recipes||[]).map(x=>[normMaster(x.name),x]));
 const enrich=(base,legacy)=>{
   const copy=JSON.parse(JSON.stringify(legacy));
   const rawItems=Array.isArray(copy.items)?copy.items:(Array.isArray(copy.ingredients)?copy.ingredients:[]);
   copy.items=rawItems.map(x=>normalizeRecipeLegacyItem(x,legacyIngredients,legacyProducts,legacyPrep));
   const fields=['code','sku','category','productType','area','department','yieldQty','yield','yieldUnit','portions','servings','salePrice','price','cost','totalCost','recipeCost','shelfLife','temperature','temp','presentation','storage','method','procedure','instructions','plating','service','recommendations','notes','theoreticalQty','wasteQty','revision','portionReferences','processPhotos','productPhoto','utensilIds'];
   const out={...base}; for(const k of fields){if(copy[k]!==undefined&&copy[k]!==null&&copy[k]!=='' )out[k]=copy[k]}
   out.items=copy.items; out.type=legacy.type==='pre'||String(copy.type||'').toLowerCase().includes('pre')?'pre':'Receta final'; out.legacyRecovered=true; out.legacyRecoveredAt=now(); return out;
 };
 const recovered=[];
 for(const legacy of allLegacy){
   const target=byId.get(String(legacy.id))||byName.get(normMaster(legacy.name));
   if(target){const merged=enrich(target,legacy);Object.assign(target,merged);recovered.push(target.id);}
   else{
     const key=legacy.type==='pre'?'preps':'recipes';
     const exists=(state[key]||[]).some(x=>String(x.id)===String(legacy.id)||normMaster(x.name)===normMaster(legacy.name));
     if(!exists)state[key].push(enrich({},legacy));
   }
 }
 const currentLegacy=[...(state.recipes||[]),...(state.preps||[])];
 for(const r of currentLegacy){const target=byId.get(String(r.id))||byName.get(normMaster(r.name));if(target&&Array.isArray(r.items)&&r.items.length){Object.assign(target,enrich(target,r));}}
 state._recipeLegacyRecovered={at:now(),count:recovered.length,total:allLegacy.length,sourceKeys:['lrx_finalrecipes_v3','lrx_preparations_v2','lrx_ingredients_v1','lrx_products']};
}

state.masterOverrides=state.masterOverrides&&typeof state.masterOverrides==='object'?state.masterOverrides:{};
state.masterUnits=Array.isArray(state.masterUnits)?state.masterUnits:[];state.masterConversions=Array.isArray(state.masterConversions)?state.masterConversions:[];state.productSuppliers=Array.isArray(state.productSuppliers)?state.productSuppliers:[];state.productIngredients=Array.isArray(state.productIngredients)?state.productIngredients:[];state.catalogCategories=Array.isArray(state.catalogCategories)?state.catalogCategories:[];state.masterHidden=state.masterHidden&&typeof state.masterHidden==='object'?state.masterHidden:{};for(const k of ['products','recipes','preps'])state.masterHidden[k]=Array.isArray(state.masterHidden[k])?state.masterHidden[k]:[];
function masterRecipeIsPrep(r){const t=String(r?.type||r?.kind||r?.classification||'').trim().toLowerCase();return t==='pre'||t.includes('pre-elabor')||t.includes('preelabor');}
function effectiveMaster(type){
 const isPrep=type==='preps';
 const isSupplier=type==='suppliers';
 const base=isSupplier?((state.suppliers&&state.suppliers.length)?state.suppliers:(master.suppliers||[]).map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x}:x)):(type==='products'?(master.products||[]):(master.recipes||[]).filter(r=>isPrep?masterRecipeIsPrep(r):!masterRecipeIsPrep(r)));
 const hidden=new Set(state.masterHidden[isPrep?'recipes':type]||[]);
 const overrides=state.masterOverrides[isPrep?'recipes':type]||{};
 return base.filter(x=>!hidden.has(String(x.id))).map(x=>({...x,...(overrides[x.id]||{})}));
}
function migrateLegacyMasterRecipeEdits(){
 const overrides=state.masterOverrides.recipes=state.masterOverrides.recipes&&typeof state.masterOverrides.recipes==='object'?state.masterOverrides.recipes:{};
 for(const key of ['recipes','preps']){
   const rows=Array.isArray(state[key])?state[key]:[];
   const migrated=[];
   for(const r of rows){
     const mid=r?.masterId?String(r.masterId):'';
     if(!mid){migrated.push(r);continue;}
     const base=(master.recipes||[]).find(x=>String(x.id)===mid);
     if(!base){migrated.push(r);continue;}
     const copy=JSON.parse(JSON.stringify(r));
     delete copy.id; delete copy.createdAt;
     overrides[mid]={...(overrides[mid]||{}),...copy,masterId:base.id,source:'EDITADO DESDE MAESTRO',updatedAt:r.updatedAt||now()};
     (state.documents||[]).forEach(d=>{if(String(d.contextRecordId||'')===String(r.id))d.contextRecordId=base.id;});
     if(Array.isArray(state.masterHidden.recipes))state.masterHidden.recipes=state.masterHidden.recipes.filter(x=>String(x)!==mid);
   }
   state[key]=rows.filter(r=>!r?.masterId||!(master.recipes||[]).some(x=>String(x.id)===String(r.masterId)));
 }
}
function findRecipeAny(type,id){const key=type==='final'?'recipes':'preps';return (state[key]||[]).find(x=>String(x.id)===String(id)) || effectiveMaster(type==='final'?'recipes':'preps').find(x=>String(x.id)===String(id));}
function cloneMasterProduct(id){const base=(master.products||[]).find(x=>String(x.id)===String(id));if(!base)return null;const clone={...base,id:'USR-P-'+Date.now(),masterId:base.id,source:'EDITADO DESDE SUP',createdAt:now()};state.products.push(clone);state.masterHidden.products.push(base.id);save();return clone;}
function cloneMasterRecipe(type,id){const key=type==='final'?'recipes':'preps';const base=(master.recipes||[]).find(x=>String(x.id)===String(id));if(!base)return null;const clone=JSON.parse(JSON.stringify({...base,id:'USR-'+(type==='final'?'R-':'P-')+Date.now(),masterId:base.id,source:'EDITADO DESDE MAESTRO',createdAt:now()}));state[key].push(clone);state.masterHidden.recipes.push(base.id);save();return clone;}
