function utensilModal(after){
 const wrap=recipeSubModal(`<div class="utensil-create"><h3>Crear nuevo utensilio</h3><p class="muted">Quedará disponible para todas las recetas y pre-elaborados.</p><div class="formgrid"><div class="field full"><label>Nombre</label><input id="utName" placeholder="Ej. Cuchillo para filetear"></div><div class="field"><label>Categoría</label><select id="utCat"><option>Corte</option><option>Preparación</option><option>Cocción</option><option>Medición</option><option>Montaje</option><option>Servicio</option><option>Control</option><option>Seguridad</option><option>Bar</option><option>Otro</option></select></div><div class="field"><label>Icono de referencia</label><select id="utIcon">${utensilIconChoices().map(([i,l])=>`<option value="${esc(i)}">${esc(i)} ${esc(l)}</option>`).join('')}</select></div><div class="field full"><label>Fotografía real</label><input id="utPhoto" type="file" accept="image/*"></div></div><div class="actions"><button class="btn" id="cancelNewUtensil">Cancelar</button><button class="btn primary" id="saveUtensil">Guardar utensilio</button></div></div>`); if(!wrap)return;
 const $=sel=>wrap.querySelector(sel); $('#cancelNewUtensil').onclick=()=>{wrap.remove();after?.()}; $('#saveUtensil').onclick=()=>{const name=$('#utName').value.trim();if(!name)return toast('Indica el nombre');const cat=$('#utCat').value.trim()||'Otro',icon=$('#utIcon').value||'🍴',f=$('#utPhoto').files?.[0];const finish=async photo=>{state.recipeUtensils=Array.isArray(state.recipeUtensils)?state.recipeUtensils:[];const id='UT-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);state.recipeUtensils.push({id,name,category:cat,photo:photo?await recolorUtensilArtwork(photo):utensilSvg(name,icon),icon,photoSource:photo?'USER_UPLOAD':'USER_VECTOR',active:true,createdAt:now()});save();wrap.remove();toast('Utensilio creado');after?.()};if(f){const rd=new FileReader();rd.onload=()=>finish(String(rd.result||''));rd.readAsDataURL(f)}else finish('')};
}
async function readRecipeImportFile(file){if(!file)throw new Error('Selecciona un archivo');const ext=fileExt(file.name);if(ext==='txt'||ext==='csv'||file.type==='text/plain'||file.type==='text/csv')return {text:await file.text(),layout:[]};if(ext==='xlsx'||ext==='xls'){if(!window.XLSX)throw new Error('Motor Excel no disponible.');const wb=window.XLSX.read(await file.arrayBuffer(),{type:'array'});let text='';for(const ws of wb.SheetNames)text+=(text?'\n':'')+window.XLSX.utils.sheet_to_csv(wb.Sheets[ws]);return {text,layout:[]}}if(!window.LRXPurchaseEngine)throw new Error('Motor OCR no disponible');const r=await window.LRXPurchaseEngine.readDocument(file);if(!String(r?.text||'').trim())throw new Error('No se detectó texto. Si es un PDF escaneado, verifica que OCR externo esté disponible.');return r}
function recipeImportReviewModal(target,file,p){const isBar=target==='barRecipe'||target==='barPrep',type=target==='final'?'final':'prep';modal(`<h3>Revisión de receta importada</h3><p class="muted">OCR terminado. <b>Revisa antes de guardar.</b> Las coincidencias de ingredientes se revisan en la ficha.</p><div class="formgrid"><div class="field full"><label>Nombre</label><input id="riName" value="${esc(p.name||'')}"></div><div class="field"><label>Tipo de producto</label><select id="riProductType"><option ${String(p.productType|| (isBar?'Producto para Bar':(type==='prep'?'Pre-elaborado':'Producto Final'))) === 'Producto Final'?'selected':''}>Producto Final</option><option ${String(p.productType||'')==='Pre-elaborado'?'selected':''}>Pre-elaborado</option><option ${String(p.productType||'')==='Ingrediente'?'selected':''}>Ingrediente</option><option ${String(p.productType||'')==='Producto para Bar'?'selected':''}>Producto para Bar</option></select></div><div class="field"><label>Área</label><select id="riArea"><option ${p.area==='Cocina'&&!isBar?'selected':''}>Cocina</option><option ${p.area==='Bar'||isBar?'selected':''}>Bar</option><option ${p.area==='Producción'?'selected':''}>Producción</option></select></div><div class="field"><label>Clasificación</label><input id="riCategory" value="${esc(p.category||'Cocina')}"></div><div class="field"><label>Rendimiento</label><input id="riYield" type="number" min=".001" step=".001" value="${Number(p.yieldQty||1)}"></div><div class="field"><label>Unidad</label><select id="riUnit">${['unidad','oz','lb','kg','g','mL','L','gal','qt','pt'].map(u=>`<option ${normalizeRecipeUnit(p.yieldUnit)===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>Porciones</label><input id="riPortions" type="number" min="0" value="${Number(p.portions||0)||''}"></div><div class="field"><label>Vida útil</label><input id="riShelf" value="${esc(p.shelfLife||'')}"></div><div class="field"><label>Temperatura</label><input id="riTemp" value="${esc(p.temperature||'')}"></div><div class="field full"><label>Almacenamiento</label><input id="riStorage" value="${esc(p.storage||'')}"></div></div><div class="card"><h4>Ingredientes detectados (${p.items.length})</h4><div id="riItems">${p.items.map(x=>`<div class="recipe-row ri-import-row"><input class="ri-name input" value="${esc(x.product)}"><input class="ri-qty input" type="number" step=".001" value="${x.qty}"><select class="ri-unit input">${['unidad','oz','lb','kg','g','mL','L','gal','qt','pt'].map(u=>`<option ${normalizeRecipeUnit(x.unit)===u?'selected':''}>${u}</option>`).join('')}</select><button class="btn danger ri-del" type="button">×</button></div>`).join('')||'<p class="muted">No se detectaron ingredientes automáticamente.</p>'}</div><button class="btn" id="riAdd">＋ Agregar ingrediente</button></div><div class="formgrid"><div class="field full"><label>Procedimiento</label><textarea id="riMethod" rows="6">${esc(p.method||'')}</textarea></div><div class="field full"><label>Plating / presentación</label><textarea id="riPlating" rows="3">${esc(p.plating||'')}</textarea></div><div class="field full"><label>Notas</label><textarea id="riNotes" rows="3">${esc(p.notes||'')}</textarea></div></div><div class="resultbox"><b>Original:</b> ${esc(file?.name||'—')} · ${String(p.rawText||'').length.toLocaleString('es-US')} caracteres extraídos.</div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="riContinue">Continuar a ficha</button></div>`);document.getElementById('riAdd')?.addEventListener('click',()=>document.getElementById('riItems')?.insertAdjacentHTML('beforeend',`<div class="recipe-row ri-import-row"><input class="ri-name input"><input class="ri-qty input" type="number" step=".001"><select class="ri-unit input">${['unidad','oz','lb','kg','g','mL','L','gal','qt','pt'].map(u=>`<option>${u}</option>`).join('')}</select><button class="btn danger ri-del" type="button">×</button></div>`));document.getElementById('riItems')?.addEventListener('click',e=>e.target.closest('.ri-del')?.parentElement.remove());document.getElementById('riContinue').onclick=()=>{const q={name:document.getElementById('riName').value.trim(),productType:document.getElementById('riProductType').value,area:document.getElementById('riArea').value,category:document.getElementById('riCategory').value.trim()||'Cocina',yieldQty:Number(document.getElementById('riYield').value||1),yieldUnit:document.getElementById('riUnit').value,portions:Number(document.getElementById('riPortions').value||0),shelfLife:document.getElementById('riShelf').value.trim(),temperature:document.getElementById('riTemp').value.trim(),storage:document.getElementById('riStorage').value.trim(),method:document.getElementById('riMethod').value,plating:document.getElementById('riPlating').value,notes:document.getElementById('riNotes').value,items:[...document.querySelectorAll('.ri-import-row')].map(r=>({product:r.querySelector('.ri-name')?.value.trim()||'',qty:Number(r.querySelector('.ri-qty')?.value||0),unit:r.querySelector('.ri-unit')?.value||'unidad'})).filter(x=>x.product&&x.qty>0)};window._lrxRecipeAttachments=[{file}];close();if(isBar){barModal(target==='barPrep'?'PREP':'RECIPE');requestAnimationFrame(()=>fillBarFormFromImport(q))}else{recipeModal(type);requestAnimationFrame(()=>fillRecipeFormFromImport(q))}}}
function fillRecipeFormFromImport(p){const set=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v??''};set('rn',p.name);set('rArea',p.area);set('rc',p.category);set('ry',p.yieldQty);set('ru',p.yieldUnit);set('rPortions',p.portions);set('rShelf',p.shelfLife);set('rTemp',p.temperature);set('rStorage',p.storage);set('rMethod',p.method);set('rPlating',p.plating);set('rNotes',p.notes);const box=document.getElementById('ingredientRows');if(box){box.innerHTML=(p.items?.length?p.items:[{product:'',qty:'',unit:'unidad'}]).map((x,i)=>recipeRow(x,i)).join('');bindRecipeRows();calculateRecipe()}}
function fillBarFormFromImport(p){const set=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v??''};set('brName',p.name);set('brDept','Bar');set('brYield',p.yieldQty);set('brUnit',p.yieldUnit);const box=document.getElementById('barIngredientRows');if(box){box.innerHTML=(p.items?.length?p.items:[{product:'',qty:'',unit:'unidad'}]).map((x,i)=>barIngredientRow(x,i)).join('');bindBarRows()}}
function barImportChoice(){modal(`<h3>Importar en Bar</h3><p class="muted">Selecciona el tipo de registro.</p><div class="actions"><button class="btn primary" id="bir">🍹 Receta de Bar</button><button class="btn" id="bip">🧪 Pre-elaborado de Bar</button><button class="btn" data-action="close">Cancelar</button></div>`);document.getElementById('bir').onclick=()=>{close();recipeImportAction('barRecipe')};document.getElementById('bip').onclick=()=>{close();recipeImportAction('barPrep')}}
function parseRecipeImportText(text){
 const raw=String(text||'').replace(/\r/g,'').split('\n').map(x=>x.replace(/\s+/g,' ').trim()).filter(Boolean);
 const stop=/^(ingredientes?|ingredients?|componentes?|procedure|procedimiento|preparation|preparacion|preparación|instructions?|instrucciones|method|metodo|método|yield|rendimiento|notes?|notas?|serving|porciones?|food cost|cost|costo|price|precio)$/i;
 const units='oz|fl\\s*oz|lb|lbs|kg|g|ml|mL|l|lt|liter|litro|unidad|unidades|ea|each|pieza|piezas|qt|gal|galon|gallon|pt';
 const unitRe=new RegExp(units,'i');
 let name='';
 for(const line of raw.slice(0,12)){
  const n=line.replace(/^[#\-•*\d.\s]+/,'').trim();
  if(n && !stop.test(n) && !/^(la reyna|receta estandar|receta estándar|ficha tecnica|ficha técnica|escandallo)/i.test(n) && n.length>2){name=n;break}
 }
 const items=[]; const seen=new Set();
 const add=(product,qty,unit)=>{product=String(product||'').replace(/^[#\-•*]+/,'').trim();unit=String(unit||'unidad').trim();qty=Number(String(qty).replace(',','.'));if(!product||!(qty>0))return;const k=product.toLowerCase()+'|'+qty+'|'+unit.toLowerCase();if(seen.has(k))return;seen.add(k);items.push({product,qty,unit})};
 for(let line of raw){
  if(stop.test(line)||/^(ingredientes?|ingredients?)/i.test(line))continue;
  let m=line.match(new RegExp('^(.+?)\\s+(\\d+(?:[\\.,]\\d+)?)\\s*('+units+')\\s*$','i'));
  if(m){add(m[1],m[2],m[3]);continue}
  m=line.match(new RegExp('^(\\d+(?:[\\.,]\\d+)?)\\s*('+units+')\\s+(.+)$','i'));
  if(m){add(m[3],m[1],m[2]);continue}
  m=line.match(new RegExp('^(.+?)\\s*[:\-]\s*(\\d+(?:[\\.,]\\d+)?)\\s*('+units+')\\b','i'));
  if(m){add(m[1],m[2],m[3]);continue}
 }
 let yieldQty=1,yieldUnit='orden',portions=0;
 for(const line of raw){let m=line.match(new RegExp('(?:yield|rendimiento)\\s*[:\-]?\\s*(\\d+(?:[\.,]\\d+)?)\\s*('+units+')?','i'));if(m){yieldQty=Number(m[1].replace(',','.'));yieldUnit=m[2]||'orden';break}m=line.match(/(?:porciones|servings?)\s*[:\-]?\s*(\d+)/i);if(m)portions=Number(m[1])}
 const methodStart=raw.findIndex(x=>/^(procedure|procedimiento|method|método|metodo|preparation|preparacion|preparación|instructions?|instrucciones)$/i.test(x));
 const notesStart=raw.findIndex(x=>/^(notes?|notas?)$/i.test(x));
 const method=methodStart>=0?raw.slice(methodStart+1,notesStart>methodStart?notesStart:methodStart+8).join('\n'):'';
 const notes=notesStart>=0?raw.slice(notesStart+1,notesStart+5).join('\n'):'';
 return {name:name||'Receta importada',productType:'Producto Final',area:'Cocina',category:'Cocina',yieldQty,yieldUnit,portions,items,method,plating:'',notes};
}
async function recipeImportAction(target='final'){const input=document.createElement('input');input.type='file';input.accept='image/*,application/pdf,.txt,.csv,.xlsx,.xls';input.style.display='none';document.body.appendChild(input);input.onchange=async()=>{const file=input.files?.[0];input.remove();if(!file)return;modal(`<h3>Procesando receta</h3><p class="muted">${esc(file.name)}</p><div class="resultbox">Extrayendo texto. Los PDF escaneados se convierten página por página a imagen y pasan por OCR.</div>`);try{const r=await readRecipeImportFile(file),p=parseRecipeImportText(r.text);p.rawText=r.text;recipeImportReviewModal(target,file,p)}catch(e){console.error('LRX recipe import',e);modal(`<h3>No se pudo procesar el archivo</h3><p>${esc(e?.message||e)}</p><div class="resultbox">No se inventaron datos. Prueba con JPG/PNG o un PDF con mejor resolución.</div><div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`)}};input.click()}
function recipeYieldUnits(current=''){
 const builtins=['unidad','oz','lb','kg','g','mL','L','gal','qt','pt'];
 const custom=(state.masterUnits||[]).map(u=>String(u.symbol||u.name||'').trim()).filter(Boolean);
 return [...new Set([...builtins,...custom,String(current||'').trim()].filter(Boolean))];
}
function createRecipeYieldUnit(selectId='ru'){
 const name=prompt('Nombre de la nueva unidad de rendimiento (ej. bandeja, jarra, porción):');
 if(!name?.trim())return;
 const symbol=prompt('Símbolo de la unidad (ej. bdj, jra, porción):',name.trim());
 if(!symbol?.trim())return;
 const dup=(state.masterUnits||[]).find(u=>normMaster(u.name)===normMaster(name)||normMaster(u.symbol)===normMaster(symbol));
 if(dup){const el=document.getElementById(selectId);if(el){el.value=dup.symbol||dup.name;}return toast('La unidad ya existe y fue seleccionada.');}
 state.masterUnits=[...(state.masterUnits||[]),{id:'UNIT-'+Date.now(),name:name.trim(),symbol:symbol.trim(),type:'Unidad',baseUnit:symbol.trim(),factor:1,source:'RECETA',createdAt:now(),updatedAt:now()}];
 save();
 const el=document.getElementById(selectId);if(el){el.innerHTML=recipeYieldUnits(symbol).map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('')+'<option value="__custom">＋ Crear unidad</option>';el.value=symbol.trim();}
 toast('Unidad de rendimiento creada y guardada');
}
