function recipeProcessStepMarkup(items){return items.map((ph,i)=>`<div class="recipe-process-step" data-step-index="${i}"><div class="recipe-process-step-title"><b>Paso ${i+1}</b><button type="button" class="btn danger recipe-step-remove">Eliminar</button></div><textarea class="input recipe-step-caption" maxlength="500" rows="3" placeholder="Describe qué se hace en este paso…">${esc(ph.caption||'')}</textarea><div class="recipe-step-attach"><button type="button" class="btn recipe-step-photo">🖼️ ${ph.file?'Cambiar foto':ph.dataUrl?'Cambiar foto':'Elegir foto del paso'}</button><input type="file" class="recipe-step-file" accept="image/*" hidden><span class="muted recipe-step-filename">${esc(ph.file?.name||ph.name||(ph.dataUrl?'Foto guardada':'Sin foto adjunta'))}</span></div>${ph.file?`<img class="recipe-step-preview" src="${esc(ph.previewUrl||'') }" alt="Foto seleccionada del paso ${i+1}">`:ph.dataUrl?`<img class="recipe-step-preview" src="${esc(ph.dataUrl)}" alt="Foto del paso ${i+1}">`:''}</div>`).join('')||'<div class="resultbox">Aún no agregas pasos. Cada paso puede tener su descripción y su propia foto.</div>'}
function recipeRow(x,i){return `<div class="recipe-row" data-i="${i}"><input class="ri-product input" list="productChoices" placeholder="Producto / ingrediente" value="${esc(x.product||x.ingredient||'')}"><input class="ri-qty input" type="number" step="0.001" placeholder="Cantidad" value="${esc(x.qty??'')}"><select class="ri-unit input"><option ${x.unit==='lb'?'selected':''}>lb</option><option ${x.unit==='oz'?'selected':''}>oz</option><option ${x.unit==='kg'?'selected':''}>kg</option><option ${x.unit==='g'?'selected':''}>g</option><option ${x.unit==='unidad'?'selected':''}>unidad</option><option ${x.unit==='L'?'selected':''}>L</option><option ${x.unit==='mL'?'selected':''}>mL</option><option ${x.unit==='lt'?'selected':''}>lt</option></select><span class="ri-cost">$0.00</span><button type="button" class="btn danger ri-remove">×</button></div>`}
function sharedProduct(name,id){const key=String(name||'').trim().toLowerCase();const masterId=id?String(id):'';const base=(master.products||[]).find(p=>(masterId&&String(p.id)===masterId)||String(p.name||'').trim().toLowerCase()===key);const override=base?(state.masterOverrides?.products?.[base.id]||{}):{};const local=(state.products||[]).find(p=>(masterId&&String(p.id)===masterId)||String(p.name||'').trim().toLowerCase()===key);const inv=(state.inventory||[]).find(x=>(masterId&&String(x.productId||'')===masterId)||String(x.product||'').trim().toLowerCase()===key);const p={...(base||{}),...override,...(local||{})};if(!Object.keys(p).length)return null;if(inv&&Number.isFinite(Number(inv.unitCost))&&Number(inv.unitCost)>0)p.cost=Number(inv.unitCost);return p}
function upsertLocalProductCost(productId,name,patch){
 const key=String(name||'').trim().toLowerCase();
 let p=(state.products||[]).find(x=>(productId&&String(x.id)===String(productId))||String(x.name||'').trim().toLowerCase()===key);
 if(!p){const m=(master.products||[]).find(x=>(productId&&String(x.id)===String(productId))||String(x.name||'').trim().toLowerCase()===key);if(!m)return null;p={...m,id:m.id||'P-'+Date.now(),source:'MASTER_OVERRIDE'};state.products.push(p)}
 Object.assign(p,patch,{updatedAt:now()});return p}
function findCost(name){const p=sharedProduct(name);return p?Number(p.finalCost||p.cost||p.price||0):0}
function unitToBase(q,u){const m={g:1,oz:28.349523125,lb:453.59237,kg:1000};const v={mL:1,'fl oz':29.5735295625,L:1000,lt:1000,pt:473.176473,qt:946.352946,gal:3785.411784};if(m[u])return {group:'mass',v:q*m[u]};if(v[u])return {group:'vol',v:q*v[u]};return {group:'unit',v:q}}
function calculateRecipe(){let total=0;document.querySelectorAll('.recipe-row').forEach(row=>{const name=row.querySelector('.ri-product')?.value||'';const q=Number(row.querySelector('.ri-qty')?.value||0);const u=row.querySelector('.ri-unit')?.value||'lb';let c=findCost(name);const p=(master.products||[]).find(x=>String(x.name).toLowerCase()===name.toLowerCase());if(p&&p.unit&&p.unit!==u){const a=unitToBase(1,p.unit),b=unitToBase(q,u);if(a.group===b.group)c*=b.v/a.v;else c*=q}else c*=q;total+=c;const out=row.querySelector('.ri-cost');if(out)out.textContent=money(c)});const y=Number(document.getElementById('ry')?.value||0);const rc=document.getElementById('recipeCost');if(rc)rc.textContent=money(total);const ru=document.getElementById('ru')?.value||'u';const ruc=document.getElementById('recipeUnitCost');if(ruc)ruc.textContent=y?`· ${money(total/y)} por ${ru}`:'';return total}
function bindRecipeRows(){document.querySelectorAll('.recipe-row').forEach(row=>{const input=row.querySelector('.ri-product');const syncLink=()=>{const value=input.value.trim().toLowerCase();const option=[...(master.products||[]),...effectiveMaster('preps')].find(x=>String(x.name||'').trim().toLowerCase()===value);delete input.dataset.productId;delete input.dataset.prepId;if(option){if((master.products||[]).some(x=>String(x.id)===String(option.id)))input.dataset.productId=option.id;else input.dataset.prepId=option.id}};row.querySelectorAll('input,select').forEach(x=>x.oninput=()=>{if(x===input)syncLink();calculateRecipe()});syncLink();row.querySelector('.ri-remove').onclick=()=>{if(document.querySelectorAll('.recipe-row').length>1){row.remove();calculateRecipe()}}})}
function duplicateRecipe(type,id){
 const key=type==='final'?'recipes':'preps';
 const base=findRecipeAny(type,id);
 if(!base)return toast('Receta no encontrada.');
 const copy=JSON.parse(JSON.stringify(base));
 const baseName=String(base.name||'Receta').trim();
 const suffix=' - COPIA';
 let name=baseName+suffix;
 let n=2;
 while((state[key]||[]).some(x=>String(x.name||'').trim().toLowerCase()===name.toLowerCase())) name=baseName+suffix+' '+n++;
 const newId=`USR-${type==='final'?'R':'P'}-${Date.now()}`;
 copy.id=newId; delete copy.masterId; copy.source='DUPLICADO'; copy.name=name; copy.createdAt=now(); copy.updatedAt=now();
 copy.history=[...(Array.isArray(base.history)?base.history:[]),{date:now(),user:currentUser().name,action:'DUPLICATE',fromId:base.id}];
 state[key]=Array.isArray(state[key])?state[key]:[]; state[key].push(copy);
 const docs=(state.documents||[]).filter(d=>String(d.contextRecordId||'')===String(base.id));
 if(docs.length){state.documents=Array.isArray(state.documents)?state.documents:[];for(const d of docs){const nd={...d,id:'DOC-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),contextRecordId:newId,name:d.name,description:`Documento duplicado desde ${baseName}`,createdAt:now()};state.documents.unshift(nd)}}
 save();audit('RECETA_DUPLICADA',`${base.id} → ${newId} · ${name}`);close();render();toast(`Receta duplicada como “${name}”. Ahora puedes cambiar la proteína y guardar.`);
}

