 Object.assign(p,{productTypeLabel:document.getElementById('epProductType')?.value.trim()||p.productTypeLabel||p.productType||'Producto terminado',department:document.getElementById('epDept')?.value.trim()||'',employee:document.getElementById('epEmployee')?.value.trim()||'',shelfLife:Number(document.getElementById('epLife')?.value||0),notes:document.getElementById('epNotes')?.value.trim()||''});
