function reverseProductionRefrigeration(p){
 if(!p)return {ok:false,reason:'Producción inexistente'};
 const moves=(state.refrigerationMoves||[]).filter(m=>String(m.productionId||'')===String(p.id));
 if(!moves.length)return {ok:true};
 const net=moves.reduce((a,m)=>a+(String(m.type).toUpperCase()==='SALIDA'?-1:1)*Number(m.qty||0),0);
 if(net<=0)return {ok:true};
 const summary=fridgeSummary()[String(p.productId||p.recipeId||p.product||'').toLowerCase()];
 if(!summary || Number(summary.qty||0)+1e-9<net)return {ok:false,reason:`No se puede eliminar ${p.product}: la producción ya salió parcialmente de la nevera.`};
 state.refrigerationMoves.push({id:'FRG-'+Date.now()+'-REV',date:now(),type:'SALIDA',product:p.product,productId:p.productId||p.recipeId||'',qty:net,unit:p.unit||'u',responsible:currentUser().name||'',productionId:p.id,notes:'Reversión por eliminación de producción',createdAt:now()});
 return {ok:true};
}
function deleteProduction(id){const p=state.production.find(x=>String(x.id)===String(id));if(!p)return;if(!confirm('¿Eliminar esta producción? Si ya estaba finalizada, se revertirán sus movimientos de inventario y nevera.'))return;if(p.status==='completed'){const rev=reverseProductionInventory(p);if(!rev.ok)return toast(rev.reason);const fridgeRev=reverseProductionRefrigeration(p);if(!fridgeRev.ok)return toast(fridgeRev.reason);}state.production=state.production.filter(x=>x.id!==id);state.labels=(state.labels||[]).filter(x=>x.productionId!==id);save();render();toast('Producción eliminada y movimientos revertidos')}
