 state.settings.customLabelTypes=Array.isArray(state.settings.customLabelTypes)?state.settings.customLabelTypes:[];
 const builtins=[['preelaborado','Pre elaborado'],['orden','Órdenes'],['ingrediente','Ingrediente'],['producto','Producto terminado'],['otro','Otro']];
 const custom=state.settings.customLabelTypes.map((x,i)=>({key:`custom:${x.id||i}`,label:String(x.label||x.name||'Tipo personalizado')}));
