function inventoryMasterRows(){
 const local=Array.isArray(state.inventory)?state.inventory:[];
 const map=new Map();
 const products=[...effectiveMaster('products'),...(state.products||[])];
 const norm=v=>String(v??'').trim().toLowerCase();
 const codeNorm=v=>String(v??'').replace(/[^A-Za-z0-9]/g,'').toLowerCase();
 const productKey=p=>codeNorm(p.code||p.sku||p.itemCode||p.upc||p.barcode)||norm(p.name);
 const convertQty=(qty,from,to,p)=>{const q=Number(qty||0);if(!q)return 0;try{if(window.LRXCost?.convert)return Number(window.LRXCost.convert(q,from,to,p?.density));}catch(e){}return norm(from)===norm(to)?q:null};
 const findProductForInventory=x=>products.find(p=>(x.productId&&String(p.id)===String(x.productId))||(x.code&&codeNorm(x.code)&&codeNorm(x.code)===productKey(p))||norm(p.name)===norm(x.product));
 const addProduct=p=>{
  if(!p||!p.name)return;
  const key=String(p.masterId||p.id||productKey(p)).toLowerCase();
  const standard=String(p.standardUnit||p.unit||'unidad');
  let row=map.get(key);
  if(!row){row={id:'INV-'+(p.id||key),productId:p.id||'',product:p.name,category:p.category||'',barcode:p.barcode||'',unit:standard,qty:0,minQty:Number(p.minQty??p.min??0),maxQty:Number(p.maxQty??p.max??0),emergency:Number(p.emergency||0),unitCost:Number(p.finalCost??p.cost??0),supplier:p.supplier||'',source:p.source||'MASTER'};map.set(key,row)}
  const matching=local.filter(x=>{const linked=x.productId&&p.id&&String(x.productId)===String(p.id);const named=norm(x.product)===norm(p.name);return linked||named});
  let qty=0,value=0,hasCost=false;
  matching.forEach(x=>{const from=String(x.unit||standard),converted=convertQty(x.qty,from,standard,p);if(converted===null)return;const c=Number(x.unitCost??p.finalCost??p.cost??0);qty+=converted;value+=converted*c;if(c>0)hasCost=true;row.minQty=Math.max(Number(row.minQty||0),Number(x.minQty||0));row.maxQty=Math.max(Number(row.maxQty||0),Number(x.maxQty||0));if(!row.supplier&&x.supplier)row.supplier=x.supplier;row.locationCount=(row.locationCount||0)+(x.location?1:0)});
  row.qty+=qty;
  if(hasCost&&row.qty>0)row.unitCost=value/row.qty;
  row.category=row.category||p.category||'';row.supplier=row.supplier||p.supplier||'';row.barcode=row.barcode||p.barcode||'';
  row.presentation=p.purchaseUnit||row.presentation||'';row.packQty=Number(p.packQty||row.packQty||0);row.packUnit=p.packUnit||row.packUnit||standard;row.packPrice=Number(p.packPrice??row.packPrice??0);row.standardUnit=standard;row.standardUnitCost=Number(p.standardUnitCost??p.preMermaUnitCost??row.standardUnitCost??row.unitCost??0);row.wastePct=Number(p.wastePct??row.wastePct??0);row.yieldFactor=Number(p.yieldFactor??row.yieldFactor??(1-row.wastePct/100));row.finalCost=Number(p.finalCost??p.usableCost??row.finalCost??row.unitCost??0);row.usableUnitCost=Number(p.finalCost??p.usableCost??row.usableUnitCost??row.finalCost??row.unitCost??0);row.usableQty=Number(p.usableQty??(row.qty*row.yieldFactor));
 };
 products.forEach(addProduct);
 local.forEach(x=>{if(!findProductForInventory(x)){const key=String(x.productId||x.id||x.product||'').trim().toLowerCase();if(key&&!map.has(key))map.set(key,{...x,source:'INVENTARIO'})}});
 return [...map.values()];
}

