 modal(`<h3>🔐 Autorización para ver acceso</h3><p class="muted">Este registro contiene credenciales protegidas. Introduce la clave autorizada.</p><div class="field"><label>Clave autorizada</label><input id="nasAuthPin" type="password" autocomplete="off"></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="nasAuthConfirm">Autorizar y ver</button></div>`);
 document.getElementById('nasAuthConfirm')?.addEventListener('click',()=>{if(document.getElementById('nasAuthPin')?.value!==pin)return toast('Clave no autorizada.');close();nasRevealCredential(id,true)});
