function nasSaveRecord(id=''){
 const g=k=>document.getElementById(k)?.value?.trim()||'';const name=g('nrName');if(!name)return toast('El nombre/título es obligatorio.');
 const arr=Array.isArray(state.nasRecords)?state.nasRecords:[];const old=id?arr.find(x=>String(x.id)===String(id)):null;const recordId=old?.id||'NAS-'+Date.now();
 const obj={id:recordId,name,type:g('nrType')||'Otro',category:g('nrCategory')||'Corporativo',issuer:g('nrIssuer'),documentNumber:g('nrNumber'),owner:g('nrOwner'),status:g('nrStatus')||'ACTIVO',issueDate:g('nrIssue'),expiryDate:g('nrExpiry'),renewalDate:g('nrRenewal'),alertDays:Math.max(1,Number(g('nrAlert')||30)),cost:Number(g('nrCost')||0),renewalCost:Number(g('nrRenewCost')||0),websiteUrl:g('nrWeb'),renewalUrl:g('nrRenewUrl'),username:g('nrUser'),password:g('nrPass'),notes:g('nrNotes'),documentIds:Array.isArray(old?.documentIds)?old.documentIds:[],createdAt:old?.createdAt||now(),updatedAt:now(),createdBy:old?.createdBy||currentUser().name};
 const files=[...(document.getElementById('nrFiles')?.files||[])];
 const valid=files.filter(f=>f.size<=8*1024*1024);
 if(files.some(f=>f.size>8*1024*1024))toast('Uno o más archivos superan 8 MB y fueron omitidos.');
 const reads=valid.map(file=>new Promise(resolve=>{const fr=new FileReader();fr.onload=()=>resolve({id:'DOC-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name:file.name,type:file.type||'application/octet-stream',description:`Documento asociado a ${obj.name}`,mime:file.type||'application/octet-stream',size:file.size,dataUrl:String(fr.result||''),ocrText:'',routeArea:'NAS / Archivo Documental',routeCollection:'nasRecords',contextModule:'nas',contextRecordId:recordId,createdAt:now(),createdBy:currentUser().name});fr.onerror=()=>resolve(null);fr.readAsDataURL(file)}));
 Promise.all(reads).then(docs=>{
   state.documents=Array.isArray(state.documents)?state.documents:[];
   const clean=docs.filter(Boolean);
   for(const d of clean){state.documents.unshift(d);obj.documentIds.push(d.id)}
   state.nasRecords=id?arr.map(x=>String(x.id)===String(id)?obj:x):[obj,...arr];
   save();close();render();toast(id?(clean.length?`Documento actualizado y ${clean.length} archivo(s) adjuntado(s).`:'Documento actualizado'):(clean.length?`Documento registrado con ${clean.length} archivo(s).`:'Documento registrado'));
 });
}
