function nasArchive(){
 const rows=Array.isArray(state.nasRecords)?state.nasRecords.slice():[];const q=String(state._nasQ||'').toLowerCase().trim();const filtered=rows.filter(r=>!q||JSON.stringify({...r,password:undefined}).toLowerCase().includes(q));
 const statusCounts={act:filtered.filter(r=>nasStatus(r)==='ACTIVO').length,soon:filtered.filter(r=>nasStatus(r)==='POR VENCER').length,expired:filtered.filter(r=>nasStatus(r)==='VENCIDO').length};const renewCost=filtered.reduce((a,r)=>a+Number(r.renewalCost||0),0);const exp=filtered.filter(r=>{const d=nasDays(r);return d!==null&&d<=Math.max(1,Number(r.alertDays||30))}).sort((a,b)=>(nasDays(a)??99999)-(nasDays(b)??99999));
 return head('NAS / Archivo Documental','Centro documental LRX para documentos empresariales, vencimientos, renovaciones, costos y accesos.',`<button class="btn primary" data-action="nas-new">＋ Nuevo documento</button> <button class="btn" data-action="nas-type-new">＋ Crear tipo</button> <button class="btn" data-action="nas-export">Excel / CSV</button> <button class="btn" data-action="nas-print">🖨 Imprimir / PDF</button> <button class="btn blue" data-action="nas-voice">🎙️ Dictar destino / documento</button> <button class="btn" data-action="nas-settings">⚙ Configurar NAS</button>`)+
 `<div class="grid"><div class="card kpi"><small>Documentos registrados</small><strong>${filtered.length}</strong></div><div class="card kpi"><small>🟢 Vigentes</small><strong>${statusCounts.act}</strong></div><div class="card kpi"><small>🟡 Por vencer</small><strong>${statusCounts.soon}</strong></div><div class="card kpi"><small>🔴 Vencidos</small><strong>${statusCounts.expired}</strong></div><div class="card kpi"><small>💰 Renovaciones</small><strong>${money(renewCost)}</strong></div><div class="card kpi"><small>📎 Con archivos</small><strong>${filtered.filter(r=>nasRecordDocs(r).length).length}</strong></div></div>`+
 `<div class="card" style="margin-top:14px"><div class="toolbar"><input id="nasQ" class="input search" placeholder="Buscar documento, tipo, entidad, folio, responsable..." value="${esc(state._nasQ||'')}"></div></div>`+
 `<div class="card" style="margin-top:14px"><div class="rowhead"><div><h3>⚠️ Próximos vencimientos</h3><p class="muted">Cada registro usa su propio plazo de alerta.</p></div></div><div class="tablewrap"><table><thead><tr><th>Documento</th><th>Vence</th><th>Restan</th><th>Renovación</th><th>Costo</th><th>Acciones</th></tr></thead><tbody>${exp.slice(0,10).map(r=>{const d=nasDays(r);return `<tr><td><b>${esc(r.name)}</b><small>${esc(r.type)} · ${esc(r.issuer||'—')}</small></td><td>${esc(r.expiryDate||'—')}</td><td><span class="status">${d<0?'VENCIDO':d===0?'HOY':d+' días'}</span></td><td>${r.renewalUrl?'<span class="status">Link disponible</span>':'—'}</td><td>${money(r.renewalCost||0)}</td><td><button class="btn" data-action="nas-edit" data-id="${esc(r.id)}">Editar</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No hay vencimientos próximos.</td></tr>'}</tbody></table></div></div>`+
 `<div class="card" style="margin-top:14px"><div class="rowhead"><h3>📁 Archivo documental</h3><button class="btn" data-action="nas-print">Imprimir / PDF</button></div><div class="tablewrap"><table><thead><tr><th>ID</th><th>Documento</th><th>Tipo</th><th>Entidad</th><th>Vencimiento</th><th>Acceso</th><th>Archivos</th><th>Acciones</th></tr></thead><tbody>${filtered.map(r=>{const docs=nasRecordDocs(r);return `<tr><td><b>${esc(r.id)}</b></td><td><b>${esc(r.name)}</b><small>${esc(r.category||'')} · ${esc(r.documentNumber||'')}</small></td><td>${esc(r.type)}</td><td>${esc(r.issuer||'—')}</td><td><span class="status">${esc(nasStatus(r))}</span><br><small>${esc(r.expiryDate||'Sin vencimiento')}</small></td><td>${r.username||r.password?'🔐 Protegido':''}${r.websiteUrl||r.renewalUrl?`<br><button class="btn" data-action="nas-open-url" data-id="${esc(r.id)}">🌐 Web</button>`:''}</td><td>${docs.length?`📎 ${docs.length} <button class="btn" data-action="nas-view-docs" data-id="${esc(r.id)}">👁 Ver</button>`:'—'}</td><td class="catalog-actions"><button class="btn" data-action="nas-view" data-id="${esc(r.id)}">👁 Ver</button> <button class="btn" data-action="nas-edit" data-id="${esc(r.id)}">Editar</button> <button class="btn" data-action="nas-attach" data-id="${esc(r.id)}">📎 Adjuntar</button> ${r.username||r.password?`<button class="btn" data-action="nas-credentials" data-id="${esc(r.id)}">🔐 Ver acceso</button>`:''} <button class="btn" data-action="nas-print-one" data-id="${esc(r.id)}">🖨 Imprimir</button> <button class="btn" data-action="nas-export-one" data-id="${esc(r.id)}">⇩ Exportar</button> <button class="btn danger" data-action="nas-delete" data-id="${esc(r.id)}">Eliminar</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No hay documentos registrados. Usa “Nuevo documento” para comenzar.</td></tr>'}</tbody></table></div></div>`+
 `<div class="card" style="margin-top:14px"><h3>🧩 Tipos de documento</h3><p class="muted">Puedes crear y ampliar los tipos según las necesidades de La Reyna Xpress.</p><div class="chips">${nasTypes().map(t=>`<span class="status">${esc(t)}</span>`).join(' ')}</div></div>`;
}
