function makeSpeechRecognition(onFinal, context='voz'){
 const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!SR){toast('Este navegador no ofrece reconocimiento de voz.');return null}
 const r=new SR();
 r.lang='es-US';
 r.continuous=false;
 r.interimResults=true;
 r.maxAlternatives=3;
 r.onstart=()=>toast(`🎙️ Escuchando ${context}…`);
 r.onaudiostart=()=>toast('🎙️ Micrófono activo…');
 r.onspeechstart=()=>{};
 r.onresult=e=>{
   let interim='',final='';
   for(let i=e.resultIndex||0;i<e.results.length;i++){const t=e.results[i]?.[0]?.transcript||'';if(e.results[i].isFinal)final+=t;else interim+=t}
   const text=(final||interim).trim();
   const out=document.getElementById('voiceTranscript');if(out&&text)out.value=text;
   if(final.trim())onFinal(final.trim());
 };
 r.onerror=e=>{
   const msg={ 'not-allowed':'El micrófono fue bloqueado. Permite el micrófono para este sitio en Safari.', 'service-not-allowed':'Safari no permitió el servicio de reconocimiento de voz.', 'network':'El servicio de reconocimiento de voz no respondió. Comprueba la conexión.', 'no-speech':'No detecté voz. Pulsa Escuchar e inténtalo otra vez.' }[e?.error]||`No se pudo reconocer la voz (${e?.error||'error'}).`;
   const st=document.getElementById('voiceStatus');if(st)st.textContent=msg;toast(msg);
 };
 r.onend=()=>{const st=document.getElementById('voiceStatus');if(st&&st.textContent.includes('Escuchando'))st.textContent='Listo. Pulsa Escuchar para volver a hablar.'};
 return r;
}
function voiceModal(mode='command'){
 modal(`<h3>🎙️ ${mode==='nas'?'Dictar destino / documento':'Acción por voz'}</h3><p class="muted">Pulsa <b>Escuchar</b>, habla con claridad y espera a que aparezca el texto. Puedes volver a intentarlo las veces necesarias.</p><div class="field full"><label>Texto reconocido</label><textarea id="voiceTranscript" style="min-height:130px" placeholder="Aquí aparecerá lo que digas…"></textarea></div><div id="voiceStatus" class="resultbox">Listo para escuchar.</div><div class="actions"><button class="btn" data-action="close" id="voiceCloseBtn">Cerrar</button><button class="btn blue" id="voiceListenBtn" type="button">🎙️ Escuchar</button><button class="btn primary" id="voiceUseBtn" type="button">Usar texto</button></div>`);
 let rec=null;
 const listen=document.getElementById('voiceListenBtn'),use=document.getElementById('voiceUseBtn'),out=document.getElementById('voiceTranscript'),status=document.getElementById('voiceStatus');
 listen.onclick=()=>{if(rec){try{rec.stop()}catch(e){}rec=null;listen.textContent='🎙️ Escuchar';status.textContent='Detenido.';return}rec=makeSpeechRecognition(text=>{if(mode==='nas'){state.settings.nas=state.settings.nas||{};state.settings.nas.lastVoiceCommand=text;save();status.textContent='Texto recibido. Pulsa “Usar texto” para guardarlo.';toast('Texto de voz recibido.')}else{status.textContent='Texto recibido. Ejecutando…';handleVoiceTranscript(text);close()}},mode==='nas'?'para NAS':'la instrucción');if(!rec)return;listen.textContent='⏹ Detener';status.textContent='Escuchando…';try{rec.start()}catch(e){rec=null;listen.textContent='🎙️ Escuchar';status.textContent='No se pudo iniciar el micrófono.'}};
 use.onclick=()=>{const text=String(out?.value||'').trim();if(!text)return toast('No hay texto reconocido');if(mode==='nas'){state.settings.nas=state.settings.nas||{};state.settings.nas.lastVoiceCommand=text;save();close();toast('Comando NAS guardado')}else{handleVoiceTranscript(text);close()}};
}
