function purchaseEngineContext(){
 return {
  products:[...(master.products||[]),...(state.products||[])],
  suppliers:[...(master.suppliers||[]),...(state.suppliers||[])].map(x=>typeof x==='string'?{name:x}:x).filter(Boolean)
 };
}
async function readPurchaseDocument(file){
 if(!window.LRXPurchaseEngine)throw new Error('Motor de compras no disponible');
 const r=await window.LRXPurchaseEngine.readDocument(file);
 window._lrxPurchaseLayout=Array.isArray(r?.layout)?r.layout:[];
 return String(r?.text||'');
}
function applyInvoiceToPurchase(text){
 const parsed=parseInvoiceToPurchase(text||'');
 const set=(id,val)=>{const e=document.getElementById(id);if(e&&val!==undefined&&val!==null&&String(val)!=='')e.value=val};
 set('bs',parsed.supplier||'');set('bi',parsed.invoice||'');set('bd',parsed.date||'');set('bsub',Number(parsed.subtotal||0)?Number(parsed.subtotal).toFixed(2):'');set('btax',Number(parsed.tax||0).toFixed(2));set('btotal',Number(parsed.total||0)?Number(parsed.total).toFixed(2):'');
 const lines=Array.isArray(parsed.lines)?parsed.lines:[];const box=document.getElementById('purchaseLines');
 if(box&&lines.length){box.innerHTML=lines.map((x,i)=>purchaseLineRow({product:x.product,code:x.code,qty:x.qty,unit:x.unit,unitCost:x.unitCost},i)).join('');const products=[...(master.products||[]),...(state.products||[])];bindPurchaseLines(products);updatePurchasePreview();}
 window._lrxPurchaseAttachment=window._lrxPurchaseAttachment||{};window._lrxPurchaseAttachment.parsed=parsed;window._lrxPurchaseAttachment.ocrText=String(text||'');persistPurchaseDraft();
 return parsed;
}
function parseInvoiceToPurchase(text){
 if(!window.LRXPurchaseEngine)return {supplier:'',invoice:'',date:'',subtotal:0,tax:0,total:0,lines:[]};
 return window.LRXPurchaseEngine.parseInvoice(text,window._lrxPurchaseLayout||[],purchaseEngineContext());
}


