function deleteProduct(id){const p=state.products.find(x=>String(x.id)===String(id));if(!p)return toast('El producto maestro no se elimina desde aquí. Puedes editarlo para crear una versión local.');if(!confirm(`¿Eliminar el producto “${p.name}”?`))return;const used=(state.purchases||[]).some(x=>String(x.productId||'')===String(id))||(state.inventory||[]).some(x=>String(x.productId||'')===String(id))||(state.recipes||[]).some(r=>(r.items||[]).some(i=>String(i.productId||'')===String(id)));if(used)return toast('No se puede eliminar: el producto tiene compras, inventario o recetas vinculadas.');state.products=state.products.filter(x=>String(x.id)!==String(id));save();render();toast('Producto eliminado')}
