function supplierModal(id=''){const p=id?supplierRecordById(id):null;modal(`<h3>${p?'Editar proveedor':'Nuevo proveedor'}</h3><div class="formgrid"><div class="field full"><label>Empresa</label><input id="sn" value="${esc(p?.name||'')}"></div><div class="field"><label>Contacto</label><input id="sc" value="${esc(p?.contact||'')}"></div><div class="field"><label>Teléfono</label><input id="sp" value="${esc(p?.phone||'')}"></div><div class="field"><label>Email</label><input id="se" type="email" value="${esc(p?.email||'')}"></div><div class="field"><label>Términos de pago</label><input id="st" value="${esc(p?.terms||'')}"></div><div class="field full"><label>Notas</label><textarea id="sx">${esc(p?.notes||'')}</textarea></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-supplier" data-id="${esc(id)}">Guardar proveedor</button></div>`)}
function saveSupplier(id=''){const name=document.getElementById('sn')?.value.trim();if(!name)return toast('Indica el nombre del proveedor');const norm=v=>String(v||'').trim().toLowerCase();const dup=[...(master.suppliers||[]),...(state.suppliers||[])].map((x,i)=>typeof x==='string'?{id:'SUPP-'+String(i+1).padStart(3,'0'),name:x}:x).find(x=>String(x.id)!==String(id)&&norm(x.name)===norm(name));if(dup)return toast(`El proveedor ya existe: ${dup.name}`);let s=state.suppliers.find(x=>String(x.id)===String(id));if(!s){s={id:id&&String(id).startsWith('SUPP-')?id:nextSupplierCode(),source:'LOCAL'};state.suppliers.push(s)}Object.assign(s,{name,contact:document.getElementById('sc')?.value.trim()||'',phone:document.getElementById('sp')?.value.trim()||'',email:document.getElementById('se')?.value.trim()||'',terms:document.getElementById('st')?.value.trim()||'',notes:document.getElementById('sx')?.value.trim()||'',updatedAt:now()});save();close();render();toast('Proveedor guardado')}
