function bindOperationalModuleTools(){const iq=document.getElementById('invSearch'),iflt=document.getElementById('invFilter'),isize=document.getElementById('invSize');if(iq&&!iq.dataset.bound){iq.dataset.bound='1';iq.oninput=()=>{state._inventoryQ=iq.value;state._inventoryPage=0;render()}}if(iflt&&!iflt.dataset.bound){iflt.dataset.bound='1';iflt.onchange=()=>{state._inventoryFilter=iflt.value;state._inventoryPage=0;render()}}if(isize&&!isize.dataset.bound){isize.dataset.bound='1';isize.onchange=()=>{state._inventorySize=Number(isize.value)||25;state._inventoryPage=0;render()}}const sq=document.getElementById('supplierQ');if(sq&&!sq.dataset.bound){sq.dataset.bound='1';sq.oninput=()=>{const q=sq.value.toLowerCase().trim();document.querySelectorAll('.supplier-card').forEach(card=>card.style.display=!q||card.textContent.toLowerCase().includes(q)?'':'none')}}const mq=document.getElementById('movementQ'),mt=document.getElementById('movementType');if(mq&&!mq.dataset.bound){mq.dataset.bound='1';mq.oninput=()=>{state._movementQ=mq.value;render()}}if(mt&&!mt.dataset.bound){mt.dataset.bound='1';mt.onchange=()=>{state._movementType=mt.value;render()}}const is=document.getElementById('investmentSize');if(is&&!is.dataset.bound){is.dataset.bound='1';is.onchange=()=>{state._investmentSize=Number(is.value)||25;state._investmentPage=0;render()}}const eq=document.getElementById('employeeQ');if(eq&&!eq.dataset.bound){eq.dataset.bound='1';eq.oninput=()=>{state._employeeQ=eq.value;render()}}const gq=document.getElementById('genericQ'),gs=document.getElementById('genericSize');if(gq&&!gq.dataset.bound){gq.dataset.bound='1';gq.oninput=()=>{const key=gq.dataset.genericKey;state[`_genericQ_${key}`]=gq.value;state[`_genericPage_${key}`]=0;render()}}if(gs&&!gs.dataset.bound){gs.dataset.bound='1';gs.onchange=()=>{const key=gs.dataset.genericKey;state[`_genericSize_${key}`]=Number(gs.value)||25;state[`_genericPage_${key}`]=0;render()}}const fq=document.getElementById('fcSearch');if(fq&&!fq.dataset.bound){fq.dataset.bound='1';fq.oninput=()=>{const q=fq.value.toLowerCase().trim();document.querySelectorAll('#foodcostRows tr[data-search]').forEach(r=>r.style.display=!q||r.dataset.search.includes(q)?'':'none')}}const yg=document.getElementById('yrGross'),yc=document.getElementById('yrClean'),yunit=document.getElementById('yrUnit');[yg,yc,yunit].forEach(x=>{if(x&&!x.dataset.bound){x.dataset.bound='1';x.addEventListener(x.tagName==='SELECT'?'change':'input',calculateYieldPreview)}});const yfp=document.getElementById('yrFilterProduct'),yfs=document.getElementById('yrFilterSupplier');if(yfp&&!yfp.dataset.bound){yfp.dataset.bound='1';yfp.onchange=()=>{state._yieldProductFilter=yfp.value;render()}}if(yfs&&!yfs.dataset.bound){yfs.dataset.bound='1';yfs.oninput=()=>{state._yieldSupplierFilter=yfs.value;render()}}}

