function recolorUtensilSvg(src){
 if(!/^data:image\/svg\+xml/i.test(String(src||'')))return src;
 try{const raw=String(src),comma=raw.indexOf(',');let svg=raw.slice(0,comma).includes(';base64')?new TextDecoder().decode(Uint8Array.from(atob(raw.slice(comma+1)),c=>c.charCodeAt(0))):decodeURIComponent(raw.slice(comma+1));svg=svg.replace(/#(?:000000|000)(?![0-9a-f])/gi,'#0d3b78').replace(/\bblack\b/gi,'#0d3b78').replace(/rgb\(\s*0\s*,\s*0\s*,\s*0\s*\)/gi,'#0d3b78').replace(/currentColor/gi,'#0d3b78');return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg)}catch(e){return src}
}
async function recolorUtensilArtwork(src){const svg=recolorUtensilSvg(src);if(svg!==src||!/^data:image\/(?:png|jpe?g|webp)/i.test(String(src||'')))return svg;return await new Promise(resolve=>{const img=new Image();img.onload=()=>{try{const c=document.createElement('canvas'),ctx=c.getContext('2d',{willReadFrequently:true});c.width=img.naturalWidth;c.height=img.naturalHeight;ctx.drawImage(img,0,0);const im=ctx.getImageData(0,0,c.width,c.height),d=im.data;let opaque=0,gray=0,dark=0;for(let i=0;i<d.length;i+=4)if(d[i+3]>8){opaque++;if(Math.max(d[i],d[i+1],d[i+2])-Math.min(d[i],d[i+1],d[i+2])<18){gray++;if((d[i]+d[i+1]+d[i+2])/3<235)dark++}}if(!opaque||gray/opaque<.96||dark/opaque<.04)return resolve(src);for(let i=0;i<d.length;i+=4){if(!d[i+3])continue;const lum=(d[i]+d[i+1]+d[i+2])/3;if(lum>248){d[i+3]=0;continue}const strength=1-lum/255;d[i]=13;d[i+1]=59;d[i+2]=120;d[i+3]=Math.round(d[i+3]*strength)}ctx.putImageData(im,0,0);resolve(c.toDataURL('image/png'))}catch(e){resolve(src)}};img.onerror=()=>resolve(src);img.src=src})}
