function utensilSvg(label,iconKey=''){
 const name=String(label||'Utensilio');
 if(/tabla de corte/i.test(name)){
  const n=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let color='#fff';if(n.includes('roja'))color='#cf202d';else if(n.includes('azul'))color='#1684d8';else if(n.includes('amarilla'))color='#f4c20d';else if(n.includes('verde'))color='#178c4a';else if(n.includes('marron'))color='#8b5a2b';else if(n.includes('morada'))color='#7044a5';else if(n.includes('naranja'))color='#ef801d';else if(n.includes('negra'))color='#30343a';
  const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128"><rect x="28" y="10" width="72" height="108" rx="8" fill="'+color+'" stroke="#0d3b78" stroke-width="4"/><rect x="35" y="18" width="58" height="92" rx="4" fill="none" stroke="rgba(255,255,255,.5)" stroke-width="2"/><circle cx="40" cy="25" r="3" fill="#fff"/></svg>';
  return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg);
 }
 const file=LRX_UTENSIL_ASSET_MAP[name]||({knife:'chef_knife',scissors:'custom_scissors',spoon:'serving_spoon',fork:'serving_fork',tongs:'custom_tongs',spatula:'silicone_spatula',whisk:'whisk',board:'baking_sheet',bowl:'bowl',measure:'measuring_spoons',peeler:'peeler',grater:'grater',colander:'colander',equipment:'equipment'}[String(iconKey||'').toLowerCase()]||'equipment');
 return './assets/utensils/'+file+'.svg';
}
