function seedRecipeUtensils(){
 state.recipeUtensils=Array.isArray(state.recipeUtensils)?state.recipeUtensils:[];let changed=false;
 const legacyNames={'tazondeaceroinoxidable':['Bowl de acero inoxidable'],'bandejagastronorm':['Bandeja gastronorm / hotel pan'],'ralladorfino':['Rallador fino / microplane'],'botelladosificadora':['Botella squeeze'],'ramequin':['Ramekin'],'medidorparacocteleria':['Jigger'],'macerador':['Muddler / macerador']};
 const refreshAll=state.settings?.utensilIconStyle!=='lrx-professional-silhouette-blue-v253';
 for(const [name,category,icon] of utensilDefaults()){
  let existing=state.recipeUtensils.find(x=>normMaster(x.name)===normMaster(name)||normMaster(x.masterName||'')===normMaster(name)); if(!existing){const aliases=legacyNames[normMaster(name).replace(/[^a-z0-9]+/g,'')]||[];existing=state.recipeUtensils.find(x=>aliases.some(old=>normMaster(x.name)===normMaster(old)));if(existing){existing.name=name;changed=true}}
  if(!existing){state.recipeUtensils.push({id:'UT-'+normMaster(name).replace(/[^a-z0-9]+/g,'-')+'-'+Date.now().toString(36),name,masterName:normMaster(name),category,photo:utensilSvg(name,icon),icon,photoSource:'LRX-REFERENCIA',active:true,createdAt:now()});changed=true}
  else {if(existing.active===false)continue;if(!existing.masterName){existing.masterName=normMaster(name);changed=true}if(!existing.icon){existing.icon=icon;changed=true}if(!['UPLOAD','USER_UPLOAD','USER_VECTOR','LRX-VECTOR'].includes(existing.photoSource)&&(refreshAll||!existing.photo||existing.photoSource==='LRX-REFERENCIA')){existing.photo=utensilSvg(existing.name,existing.icon||icon);existing.photoSource='LRX-REFERENCIA';changed=true}}
 }
 if(refreshAll){for(const item of state.recipeUtensils){if(['UPLOAD','USER_UPLOAD','USER_VECTOR','LRX-VECTOR'].includes(item.photoSource)||item.active===false)continue;item.icon=item.icon||'other';item.photo=utensilSvg(item.name,item.icon);item.photoSource='LRX-REFERENCIA';}state.settings=state.settings||{};state.settings.utensilIconStyle='lrx-professional-silhouette-blue-v253';changed=true}
 if(changed)save();
}
function updateDateChip(){
 const d=state.settings?.dateRange||{};
 const from=d.from||'2025-01-01', to=d.to||'2025-12-31';
 const el=document.querySelector('.date-chip');
 if(!el)return;
 const f=new Date(from+'T12:00:00'), t=new Date(to+'T12:00:00');
 const fmtD=x=>x.toLocaleDateString('es-US',{day:'2-digit',month:'short',year:'numeric'}).replace('.','');
 el.innerHTML=`▣ <b>${fmtD(f)}</b><span>→</span><b>${fmtD(t)}</b>⌄`;
}
