function saveDigitalAsset(id=''){
 const g=x=>document.getElementById(x)?.value?.trim()||'';const name=g('daName');if(!name)return toast('Indica el nombre del activo.');
 const url=g('daUrl');if(url&& !/^https?:\/\//i.test(url))return toast('La URL debe comenzar con http:// o https://');
 const arr=Array.isArray(state.digitalAssets)?state.digitalAssets:[];let r=id?arr.find(x=>String(x.id)===String(id)):null;
 if(!r){r={id:g('daId')||'DIG-'+Date.now(),createdAt:now(),attachments:[]};arr.push(r)}
 Object.assign(r,{name,type:g('daType')||'Cuenta',status:g('daStatus')||'ACTIVO',platform:g('daPlatform'),owner:g('daOwner'),url,username:g('daUser'),password:g('daPass'),renewalDate:g('daRenew'),contact:g('daContact'),notes:g('daNotes'),updatedAt:now()});
 const files=[...(document.getElementById('daFiles')?.files||[])];
 const read=files.filter(f=>f.size<=8*1024*1024).map(f=>new Promise(resolve=>{const fr=new FileReader();fr.onload=()=>resolve({id:'ATT-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name:f.name,type:f.type,size:f.size,dataUrl:fr.result,addedAt:now()});fr.onerror=()=>resolve(null);fr.readAsDataURL(f)}));
 if(files.some(f=>f.size>8*1024*1024))toast('Algunos archivos superan 8 MB y no fueron adjuntados.');
 Promise.all(read).then(out=>{r.attachments=[...(r.attachments||[]),...out.filter(Boolean)];state.digitalAssets=arr;save();audit(id?'DIGITAL_EDIT':'DIGITAL_CREATE',`${id?'Editado':'Creado'} activo digital ${r.id} · ${r.name}`);close();render();toast('Activo digital guardado correctamente')});
}
