async function saveSupplier(id=''){const name=document.getElementById('sn')?.value.trim();if(!name)return toast('Indica el nombre del proveedor');const dup=masterSuppliers().find(x=>String(x.id)!==String(id)&&normMaster(x.name)===normMaster(name));if(dup&&String(id)!==String(dup.id))return toast('El proveedor ya existe: '+dup.name);let s=state.suppliers.find(x=>String(x.id)===String(id));if(!s){s={id:id&&String(id).startsWith('SUPP-')?id:nextSupplierCode(),source:'LOCAL'};state.suppliers.push(s)}Object.assign(s,{name,taxId:document.getElementById('sidcode')?.value.trim()||'',contact:document.getElementById('sc')?.value.trim()||'',phone:document.getElementById('sp')?.value.trim()||'',email:document.getElementById('se')?.value.trim()||'',website:document.getElementById('sweb')?.value.trim()||'',terms:document.getElementById('st')?.value.trim()||'',leadTime:Number(document.getElementById('slead')?.value||0),status:document.getElementById('sstatus')?.value||'ACTIVO',address:document.getElementById('saddr')?.value.trim()||'',notes:document.getElementById('sx')?.value.trim()||'',updatedAt:now()});const files=[...(document.getElementById('sfiles')?.files||[])].filter(f=>f.size<=8*1024*1024);if(files.length)s.attachments=[...(s.attachments||[]),...(await Promise.all(files.map(readFileDataV207))).filter(Boolean)];save();close();render();toast('Proveedor guardado')}
