function supplierDetailModal(id){const s=supplierRecordById(id);if(!s)return toast('Proveedor no encontrado');const products=masterProducts().filter(p=>normMaster(p.supplier)===normMaster(s.name));modal('<h3>Proveedor · '+esc(s.name)+'</h3><div class="grid"><div class="card kpi"><small>Productos</small><strong>'+products.length+'</strong></div><div class="card kpi"><small>Compras</small><strong>'+((state.purchases||[]).filter(x=>normMaster(x.supplier)===normMaster(s.name)).length)+'</strong></div><div class="card kpi"><small>Lead time</small><strong>'+Number(s.leadTime||0)+' días</strong></div></div><div class="card"><div class="catalog-grid"><div><small>Contacto</small><b>'+esc(s.contact||'—')+'</b></div><div><small>Teléfono</small><b>'+esc(s.phone||'—')+'</b></div><div><small>Email</small><b>'+esc(s.email||'—')+'</b></div><div><small>Website</small><b>'+esc(s.website||'—')+'</b></div><div><small>Términos</small><b>'+esc(s.terms||'—')+'</b></div><div><small>Estado</small><b>'+esc(s.status||'ACTIVO')+'</b></div></div></div><div class="card"><h4>Productos vinculados</h4>'+ (products.map(p=>'<div style="padding:6px 0;border-bottom:1px solid var(--line)"><b>'+esc(p.name)+'</b> · '+money(p.finalCost||p.cost||0)+' / '+esc(p.standardUnit||p.unit||'')+'</div>').join('')||'<p class="muted">Sin productos.</p>')+'</div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn primary" data-action="edit-supplier" data-id="'+esc(s.id)+'">Editar</button></div>')}
function bindMasterDataTools(){const iq=document.getElementById('invSearch');if(iq&&!iq.dataset.bound){iq.dataset.bound='1';iq.oninput=()=>{state._inventoryQ=iq.value;state._inventoryPage=0;render()}}const il=document.getElementById('invLoc');if(il&&!il.dataset.bound){il.dataset.bound='1';il.onchange=()=>{state._inventoryLoc=il.value;state._inventoryPage=0;render()}}const ist=document.getElementById('invStatus');if(ist&&!ist.dataset.bound){ist.dataset.bound='1';ist.onchange=()=>{state._inventoryStatus=ist.value;state._inventoryPage=0;render()}}const isz=document.getElementById('invSize');if(isz&&!isz.dataset.bound){isz.dataset.bound='1';isz.onchange=()=>{state._inventorySize=Number(isz.value)||25;state._inventoryPage=0;render()}}const q=document.getElementById('ingredientsQ');if(q&&!q.dataset.bound){q.dataset.bound='1';q.oninput=()=>{state._ingredientsQ=q.value;state._ingredientsPage=0;render()}}const sz=document.getElementById('ingredientsSize');if(sz&&!sz.dataset.bound){sz.dataset.bound='1';sz.onchange=()=>{state._ingredientsSize=Number(sz.value)||25;state._ingredientsPage=0;render()}}const cq=document.getElementById('categoriesQ');if(cq&&!cq.dataset.bound){cq.dataset.bound='1';cq.oninput=()=>{state._categoriesQ=cq.value;render()}}const sq=document.getElementById('supplierQ');if(sq&&!sq.dataset.bound){sq.dataset.bound='1';sq.oninput=()=>{state._supplierQ=sq.value;render()}}}

/* ===== v208 — INVENTARIO INTEGRAL ===== */
function inv208Products(){return [...effectiveMaster('products'),...(state.products||[])].filter((p,i,a)=>p&&p.name&&a.findIndex(x=>String(x.id||x.name).toLowerCase()===String(p.id||p.name).toLowerCase())===i)}
function inv208Locations(){const base=Array.isArray(state.settings?.inventoryLocations)?state.settings.inventoryLocations:[];const local=Array.isArray(state.inventoryLocations)?state.inventoryLocations:[];return [...new Set([...base,...local].map(x=>typeof x==='string'?x:x?.name).filter(Boolean))]}
function inv208Days(d){if(!d)return null;return Math.ceil((new Date(String(d)+'T23:59:59')-Date.now())/86400000)}
function inv208Lots(){return Array.isArray(state.inventoryLots)?state.inventoryLots:[]}
function inv208Rows(){
 const products=inv208Products(), local=Array.isArray(state.inventory)?state.inventory:[], map=new Map();
 const key=(p)=>String(p?.id||p?.code||p?.sku||p?.barcode||p?.name||'').toLowerCase();
 for(const p of products){map.set(key(p),{productId:p.id||'',product:p.name,category:p.category||'',unit:p.standardUnit||p.unit||'unidad',qty:0,unitCost:Number(p.finalCost??p.cost??0),supplier:p.supplier||'',minQty:Number(p.minQty??p.min??0),maxQty:Number(p.maxQty??p.max??0),barcode:p.barcode||p.upc||'',locations:{}})}
 for(const x of local){const p=products.find(p=>(x.productId&&String(p.id)===String(x.productId))||String(p.name||'').trim().toLowerCase()===String(x.product||'').trim().toLowerCase());const k=p?key(p):String(x.productId||x.product||x.id||'').toLowerCase();if(!k)continue;if(!map.has(k))map.set(k,{productId:x.productId||'',product:x.product||'—',category:x.category||'',unit:x.unit||'unidad',qty:0,unitCost:Number(x.unitCost||0),supplier:x.supplier||'',minQty:Number(x.minQty||0),maxQty:Number(x.maxQty||0),barcode:x.barcode||'',locations:{}});const r=map.get(k);const q=Number(x.qty||0);r.qty+=q;r.unitCost=(r.qty?q*Number(x.unitCost??r.unitCost??0)/r.qty:0)+(r.qty-q>0?Number(r.unitCost||0)*(r.qty-q)/r.qty:0);r.minQty=Math.max(r.minQty,Number(x.minQty||0));r.maxQty=Math.max(r.maxQty,Number(x.maxQty||0));r.locations[x.location||'Sin ubicación']=(r.locations[x.location||'Sin ubicación']||0)+q;r.supplier=r.supplier||x.supplier||'';r.barcode=r.barcode||x.barcode||''}
 return [...map.values()].map(r=>{const lots=inv208Lots().filter(l=>(r.productId&&String(l.productId)===String(r.productId))||String(l.product||'').toLowerCase()===String(r.product||'').toLowerCase());const activeLots=lots.filter(l=>Number(l.qty||0)>0);const exp=activeLots.map(l=>inv208Days(l.expiryDate)).filter(d=>d!==null).sort((a,b)=>a-b)[0];return {...r,lots:activeLots,nearestExpiry:exp??null}})
}
function inv208Status(r){const q=Number(r.qty||0),min=Number(r.minQty||0);if(r.nearestExpiry!==null&&r.nearestExpiry<0)return 'VENCIDO';if(r.nearestExpiry!==null&&r.nearestExpiry<=30)return 'VENCE PRONTO';if(min>0&&q<=min)return 'BAJO MÍNIMO';if(Number(r.maxQty||0)>0&&q>Number(r.maxQty))return 'SOBRE MÁXIMO';if(q<=0)return 'SIN EXISTENCIA';return 'OK'}
function inventory208(){
 const all=inv208Rows(),q=String(state._inventoryQ||'').trim().toLowerCase(),loc=state._inventoryLoc||'TODAS',st=state._inventoryStatus||'TODOS',size=Math.max(25,Number(state._inventorySize||25));
 const filtered=all.filter(r=>{const txt=JSON.stringify(r).toLowerCase();const locationOK=loc==='TODAS'||Number(r.locations?.[loc]||0)>0;const status=inv208Status(r);return (!q||txt.includes(q))&&locationOK&&(st==='TODOS'||status===st)});
 const pages=Math.max(1,Math.ceil(filtered.length/size));state._inventoryPage=Math.min(Math.max(0,Number(state._inventoryPage||0)),pages-1);const page=state._inventoryPage;const rows=filtered.slice(page*size,(page+1)*size);
 const value=all.reduce((a,r)=>a+Number(r.qty||0)*Number(r.unitCost||0),0),low=all.filter(r=>inv208Status(r)==='BAJO MÍNIMO').length,exp=all.filter(r=>r.nearestExpiry!==null&&r.nearestExpiry<=30).length,zero=all.filter(r=>Number(r.qty||0)<=0).length;
 const locations=inv208Locations();
 return head('Inventario Integral','Control de existencias, ubicaciones, lotes, vencimientos, movimientos, conteo físico y valorización.',`<button class="btn primary" data-action="inventory-receipt">＋ Recepción / Lote</button> <button class="btn" data-action="inventory-count">▣ Conteo físico</button> <button class="btn" data-action="inventory-adjust">＋ Ajuste</button> <button class="btn" data-action="new-transfer">⇄ Transferir</button> <button class="btn" data-action="inventory-import">⇩ Importar Excel / CSV</button> <button class="btn" data-action="inventory-export">Excel / CSV</button> <button class="btn" data-action="inventory-print">Imprimir / PDF</button>`)+
 `<div class="grid lrx-inv-kpis"><div class="card kpi"><small>Productos controlados</small><strong>${all.length}</strong></div><div class="card kpi"><small>Valor inventario</small><strong>${money(value)}</strong></div><div class="card kpi"><small>Bajo mínimo</small><strong>${low}</strong></div><div class="card kpi"><small>Vencen ≤30 días</small><strong>${exp}</strong></div><div class="card kpi"><small>Sin existencia</small><strong>${zero}</strong></div></div>`+
 `<div class="card lrx-inv-toolbar"><div class="toolbar"><input id="invSearch" class="input search" value="${esc(state._inventoryQ||'')}" placeholder="Buscar producto, SKU, barcode, categoría o proveedor"><select id="invLoc" class="input"><option value="TODAS">Todas las ubicaciones</option>${locations.map(x=>`<option ${loc===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="invStatus" class="input">${['TODOS','OK','BAJO MÍNIMO','VENCE PRONTO','VENCIDO','SIN EXISTENCIA','SOBRE MÁXIMO'].map(x=>`<option ${st===x?'selected':''}>${x}</option>`).join('')}</select><select id="invSize" class="input">${[25,50,100,250,381].map(n=>`<option value="${n}" ${size===n?'selected':''}>${n}</option>`).join('')}</select></div></div>`+
 `<div class="grid lrx-inv-secondary"><div class="card"><div class="rowhead"><div><h3>Alertas de inventario</h3><p class="muted">Stock, vencimientos y lotes con riesgo.</p></div><button class="btn" data-action="inventory-alerts">Ver todas</button></div><div>${all.filter(r=>['BAJO MÍNIMO','VENCE PRONTO','VENCIDO','SIN EXISTENCIA'].includes(inv208Status(r))).slice(0,8).map(r=>`<div class="lrx-inv-alert"><b>${esc(r.product)}</b><span>${esc(inv208Status(r))} · ${Number(r.qty||0)} ${esc(r.unit||'')}</span></div>`).join('')||'<div class="empty">Sin alertas críticas.</div>'}</div></div><div class="card"><div class="rowhead"><div><h3>Valorización por categoría</h3><p class="muted">Existencia × costo unitario.</p></div><button class="btn" data-action="inventory-report">Reporte</button></div><div>${Object.entries(all.reduce((m,r)=>(m[r.category||'Sin categoría']=(m[r.category||'Sin categoría']||0)+Number(r.qty||0)*Number(r.unitCost||0),m),{})).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,v])=>`<div class="lrx-inv-bar"><span>${esc(k)}</span><b>${money(v)}</b></div>`).join('')||'<div class="empty">Sin valorización.</div>'}</div></div></div>`+
 `<div class="card"><div class="rowhead"><div><h3>Existencias por producto</h3><p class="muted">${filtered.length} resultados · página ${page+1} de ${pages}</p></div><span class="pill">Actualizado ${fmt(now(),true)}</span></div><div class="tablewrap"><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Existencia</th><th>Costo</th><th>Valor</th><th>Ubicaciones</th><th>Próx. vencimiento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.productId||'—')}</b><br><small>${esc(r.barcode||'')}</small></td><td><b>${esc(r.product)}</b><small>${esc(r.supplier||'')}</small></td><td>${esc(r.category||'—')}</td><td>${Number(r.qty||0).toLocaleString(undefined,{maximumFractionDigits:3})} ${esc(r.unit||'')}</td><td>${money(r.unitCost)}</td><td>${money(Number(r.qty||0)*Number(r.unitCost||0))}</td><td>${Object.entries(r.locations||{}).filter(([,v])=>Number(v)>0).map(([k,v])=>`${esc(k)}: ${v}`).join('<br>')||'—'}</td><td>${r.nearestExpiry===null?'—':r.nearestExpiry<0?'VENCIDO':r.nearestExpiry+' días'}</td><td><span class="status">${esc(inv208Status(r))}</span></td><td class="catalog-actions"><button class="btn" data-action="inventory-view" data-id="${esc(r.productId)}">Ver</button> <button class="btn" data-action="inventory-lots" data-id="${esc(r.productId)}">Lotes</button> <button class="btn" data-action="inventory-adjust" data-id="${esc(r.productId)}">Ajustar</button> <button class="btn" data-action="inventory-count" data-id="${esc(r.productId)}">Conteo</button></td></tr>`).join('')||'<tr><td colspan="10" class="empty">No hay productos que coincidan con los filtros.</td></tr>'}</tbody></table></div><div id="inventoryPager" class="pager">${pagerMarkup('inventory-page',page,pages,filtered.length,filtered.length?page*size+1:0,Math.min((page+1)*size,filtered.length))}</div></div>`;
}
function inventory208ReceiptModal(){
 const ps=inv208Products(),locs=inv208Locations();modal(`<h3>Recepción de inventario / nuevo lote</h3><p class="muted">Registra lote, vencimiento, ubicación y costo. La existencia y el movimiento quedan trazables.</p><div class="formgrid"><div class="field full"><label>Producto *</label><input id="irProduct" list="irProducts"><datalist id="irProducts">${ps.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist></div><div class="field"><label>Cantidad *</label><input id="irQty" type="number" min="0.001" step="0.001"></div><div class="field"><label>Unidad</label><input id="irUnit" value="unidad"></div><div class="field"><label>Costo unitario *</label><input id="irCost" type="number" min="0" step="0.000001"></div><div class="field"><label>Ubicación</label><select id="irLocation">${locs.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Lote</label><input id="irLot" placeholder="Lote proveedor / interno"></div><div class="field"><label>Fecha recepción</label><input id="irDate" type="date" value="${now().slice(0,10)}"></div><div class="field"><label>Vencimiento</label><input id="irExpiry" type="date"></div><div class="field"><label>Proveedor</label><input id="irSupplier"></div><div class="field"><label>Factura / referencia</label><input id="irRef"></div><div class="field"><label>Mínimo</label><input id="irMin" type="number" step="0.001" value="0"></div><div class="field"><label>Máximo</label><input id="irMax" type="number" step="0.001" value="0"></div><div class="field full"><label>Notas</label><textarea id="irNotes" rows="2"></textarea></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-inventory-receipt">Guardar recepción</button></div>`);const p=document.getElementById('irProduct');p.oninput=()=>{const x=ps.find(v=>String(v.name).toLowerCase()===p.value.trim().toLowerCase());if(x){document.getElementById('irUnit').value=x.standardUnit||x.unit||'unidad';document.getElementById('irCost').value=Number(x.finalCost??x.cost??0);document.getElementById('irSupplier').value=x.supplier||'';document.getElementById('irMin').value=Number(x.minQty??x.min??0);document.getElementById('irMax').value=Number(x.maxQty??x.max??0)}}
}
function saveInventoryReceipt(){const g=id=>document.getElementById(id)?.value||'';const name=g('irProduct').trim(),qty=Number(g('irQty')),unit=g('irUnit').trim()||'unidad',cost=Number(g('irCost'));if(!name||!(qty>0)||!(cost>=0))return toast('Completa producto, cantidad y costo');const p=inv208Products().find(x=>String(x.name).toLowerCase()===name.toLowerCase());if(!p)return toast('Producto no encontrado en Catálogos');const loc=g('irLocation')||'Almacén',lot={id:'LOT-'+Date.now(),productId:p.id||'',product:p.name,qty,unit,unitCost:cost,location:loc,lot:g('irLot').trim(),receivedDate:g('irDate')||now().slice(0,10),expiryDate:g('irExpiry')||'',supplier:g('irSupplier').trim(),reference:g('irRef').trim(),notes:g('irNotes').trim(),status:'ACTIVO',createdAt:now(),updatedAt:now()};state.inventoryLots=[lot,...inv208Lots()];const target=state.inventory.find(x=>String(x.productId||'')===String(p.id)&&String(x.unit||unit).toLowerCase()===unit.toLowerCase()&&String(x.location||'Almacén')===loc)||null;if(target){const before=Number(target.qty||0),old=Number(target.unitCost||0);target.unitCost=(before*old+qty*cost)/(before+qty);target.qty=before+qty;target.minQty=Number(g('irMin')||target.minQty||0);target.maxQty=Number(g('irMax')||target.maxQty||0);target.lot=lot.lot;target.expiryDate=lot.expiryDate}else state.inventory.push({id:'INV-'+Date.now(),productId:p.id||'',product:p.name,unit,qty,unitCost:cost,location:loc,minQty:Number(g('irMin')||0),maxQty:Number(g('irMax')||0),supplier:g('irSupplier').trim(),lot:lot.lot,expiryDate:lot.expiryDate});state.inventoryReceipts=[{id:'REC-'+Date.now(),date:lot.receivedDate,productId:p.id||'',product:p.name,qty,unit,cost,location:loc,lot:lot.lot,expiryDate:lot.expiryDate,supplier:lot.supplier,reference:lot.reference,notes:lot.notes,createdAt:now()},...(state.inventoryReceipts||[])];state.movements.push({id:'MOV-'+Date.now(),date:now(),type:'RECEPCIÓN INVENTARIO',product:p.name,productId:p.id||'',qty,unit,unitCost:cost,total:qty*cost,location:loc,lot:lot.lot,expiryDate:lot.expiryDate,ref:lot.reference||lot.id});save();close();render();toast('Recepción y lote registrados')}
function inventory208LotsModal(id){const rows=inv208Lots().filter(l=>String(l.productId)===String(id)||(!l.productId&&String(l.product).toLowerCase()===String(inv208Rows().find(x=>String(x.productId)===String(id))?.product||'').toLowerCase())).sort((a,b)=>String(a.expiryDate||'9999').localeCompare(String(b.expiryDate||'9999')));modal(`<h3>Lotes y vencimientos</h3><div class="tablewrap"><table><thead><tr><th>Lote</th><th>Cantidad</th><th>Ubicación</th><th>Recepción</th><th>Vencimiento</th><th>Costo</th><th>Proveedor</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(l=>{const d=inv208Days(l.expiryDate);const status=Number(l.qty||0)<=0?'AGOTADO':d!==null&&d<0?'VENCIDO':d!==null&&d<=30?'VENCE PRONTO':'ACTIVO';return `<tr><td>${esc(l.lot||l.id)}</td><td>${esc(l.qty)} ${esc(l.unit||'')}</td><td>${esc(l.location||'—')}</td><td>${esc(l.receivedDate||'—')}</td><td>${esc(l.expiryDate||'—')}</td><td>${money(l.unitCost)}</td><td>${esc(l.supplier||'—')}</td><td><span class="status">${status}</span></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No hay lotes registrados.</td></tr>'}</tbody></table></div><div class="actions"><button class="btn" data-action="close">Cerrar</button></div>`)}
function inventory208AlertsModal(){const rows=inv208Rows().filter(r=>['BAJO MÍNIMO','VENCE PRONTO','VENCIDO','SIN EXISTENCIA'].includes(inv208Status(r)));modal(`<h3>Alertas de inventario</h3><div class="tablewrap"><table><thead><tr><th>Producto</th><th>Existencia</th><th>Estado</th><th>Vencimiento</th><th>Ubicación</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.product)}</td><td>${r.qty} ${esc(r.unit)}</td><td>${esc(inv208Status(r))}</td><td>${r.nearestExpiry===null?'—':r.nearestExpiry<0?'Vencido':r.nearestExpiry+' días'}</td><td>${Object.keys(r.locations||{}).join(', ')||'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay alertas.</td></tr>'}</tbody></table></div><div class="actions"><button class="btn" data-action="close">Cerrar</button><button class="btn" data-action="inventory-export-alerts">Exportar CSV</button></div>`)}
function inventory208Report(){const rows=inv208Rows().map(r=>({codigo:r.productId,producto:r.product,categoria:r.category,existencia:r.qty,unidad:r.unit,costoUnitario:r.unitCost,valor:Number(r.qty||0)*Number(r.unitCost||0),proveedor:r.supplier,ubicaciones:Object.entries(r.locations||{}).map(([k,v])=>`${k}: ${v}`).join(' | '),proximoVencimiento:r.nearestExpiry===null?'':r.nearestExpiry,estado:inv208Status(r)}));return exportExcel(rows,'inventario_integral')}
function inventory208Export(){const rows=inv208Rows().map(r=>({codigo:r.productId,producto:r.product,categoria:r.category,existencia:r.qty,unidad:r.unit,costo:r.unitCost,valor:Number(r.qty||0)*Number(r.unitCost||0),proveedor:r.supplier,barcode:r.barcode,ubicaciones:Object.entries(r.locations||{}).map(([k,v])=>`${k}: ${v}`).join(' | '),vencimiento:r.nearestExpiry===null?'':r.nearestExpiry,estado:inv208Status(r)}));return exportExcel(rows,'inventario')}
function inventory208ImportModal(){modal(`<h3>Importar inventario</h3><p class="muted">Admite CSV y XLSX. El sistema muestra una vista previa y solo guarda cuando confirmas.</p><input id="invImportFile" type="file" accept=".csv,.xlsx,.xls"><div id="invImportPreview" class="card" style="margin-top:12px"><span class="muted">Selecciona un archivo.</span></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" id="invImportSave" disabled>Importar registros</button></div>`);document.getElementById('invImportFile').onchange=e=>previewInventoryImport(e.target.files?.[0]);}
async function previewInventoryImport(file){if(!file)return;try{let rows=[];if(/\.csv$/i.test(file.name)){const text=await file.text();rows=parseCSV208(text)}else if(window.XLSX){const buf=await file.arrayBuffer(),wb=XLSX.read(buf,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{defval:''})}else throw new Error('El lector XLSX no está disponible; usa CSV o conecta a Internet para cargar SheetJS.');window._lrxInvImportRows=rows.slice(0,5000);const cols=[...new Set(rows.flatMap(x=>Object.keys(x)))];document.getElementById('invImportPreview').innerHTML=`<b>${rows.length}</b> registros detectados · columnas: ${esc(cols.join(', '))}<div class="tablewrap"><table><thead><tr>${cols.slice(0,10).map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(r=>`<tr>${cols.slice(0,10).map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;const b=document.getElementById('invImportSave');b.disabled=!rows.length;b.onclick=()=>saveInventoryImport();}catch(e){document.getElementById('invImportPreview').innerHTML=`<span class="status">Error: ${esc(e.message||e)}</span>`}}
function parseCSV208(text){const lines=text.split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return [];const parse=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&line[i+1]==='"'){cur+='"';i++;continue}if(ch==='"'){q=!q;continue}if((ch===','||ch===';')&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out};const h=parse(lines[0]);return lines.slice(1).map(l=>{const a=parse(l),o={};h.forEach((k,i)=>o[k]=a[i]??'');return o})}
function saveInventoryImport(){const rows=Array.isArray(window._lrxInvImportRows)?window._lrxInvImportRows:[];let ok=0,skip=0;for(const r of rows){const find=k=>{const key=Object.keys(r).find(x=>String(x).trim().toLowerCase()===k);return key?r[key]:''};const name=String(find('producto')||find('product')||find('nombre')||'').trim();const qty=Number(find('cantidad')||find('qty')||find('existencia')||0);if(!name||!Number.isFinite(qty)||qty<0){skip++;continue}const p=inv208Products().find(x=>String(x.name).toLowerCase()===name.toLowerCase()||String(x.id||'').toLowerCase()===String(find('codigo')||find('sku')||'').toLowerCase());if(!p){skip++;continue}const unit=String(find('unidad')||p.standardUnit||p.unit||'unidad'),loc=String(find('ubicacion')||find('location')||'Almacén'),costRaw=find('costo')||find('cost')||p.finalCost||p.cost||0,cost=Number(costRaw),lot=String(find('lote')||find('lot')||''),expiry=String(find('vencimiento')||find('expiry')||'');if(!Number.isFinite(cost)||cost<0){skip++;continue}const target=state.inventory.find(x=>String(x.productId||'')===String(p.id||'')&&String(x.unit||'').toLowerCase()===unit.toLowerCase()&&String(x.location||'Almacén')===loc);if(target){const before=Number(target.qty||0);const after=before+qty;target.unitCost=after>0?(before*Number(target.unitCost||cost)+qty*cost)/after:cost;target.qty=after}else state.inventory.push({id:'INV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),productId:p.id||'',product:p.name,unit,qty,unitCost:cost,location:loc,lot,expiryDate:expiry});if(lot||expiry)state.inventoryLots=[{id:'LOT-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),productId:p.id||'',product:p.name,qty,unit,unitCost:cost,location:loc,lot,expiryDate:expiry,receivedDate:now().slice(0,10),source:'IMPORT'},...inv208Lots()];state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),date:now(),type:'IMPORTACIÓN INVENTARIO',product:p.name,productId:p.id||'',qty,unit,unitCost:cost,total:qty*cost,location:loc,lot,expiryDate:expiry,ref:'IMPORT-'+Date.now()});ok++}save();window._lrxInvImportRows=null;close();render();toast(`Importación completada: ${ok} registros · ${skip} omitidos`)}

